import { useState } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import { LayoutDashboard, Activity, Package, GitBranch, Bell, Settings, LogOut, User } from "lucide-react";

export function LogoSeal({ size = "md" }) {
  const d = size === "sm" ? 46 : size === "lg" ? 90 : 64;
  const fs = size === "sm" ? 7 : size === "lg" ? 11 : 9;
  return (
    <div style={{ width:d, height:d, flexShrink:0, position:"relative" }}>
      <div style={{ position:"absolute", inset:0, borderRadius:"50%", background:"linear-gradient(180deg,#1d4080,#0d1e36)", border:"2px solid rgba(255,255,255,0.50)" }} />
      <div style={{ position:"absolute", inset:4, borderRadius:"50%", border:"1px solid rgba(255,255,255,0.25)" }} />
      <div style={{ position:"absolute", inset:0, display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", gap:1, padding:6 }}>
        <div style={{ display:"flex", gap:2 }}>{["★","★","★"].map((s,i)=><span key={i} style={{color:"rgba(255,255,255,0.85)",fontSize:fs-1}}>{s}</span>)}</div>
        <div style={{ textAlign:"center", lineHeight:1.1 }}>
          <div style={{ fontSize:fs+1, fontWeight:800, color:"#fff", fontFamily:"'Playfair Display',serif" }}>Lácteos</div>
          <div style={{ fontSize:fs-1, fontWeight:700, color:"rgba(255,255,255,0.85)" }}>de Oriente</div>
        </div>
        <div style={{ width:"70%", height:"0.5px", background:"rgba(255,255,255,0.40)", margin:"2px 0" }} />
        <div style={{ fontSize:fs-2, color:"rgba(255,255,255,0.60)", letterSpacing:"0.05em", textTransform:"uppercase" }}>Lo fresco mejor</div>
      </div>
    </div>
  );
}

export function LogoBanner() {
  return (
    <div style={{ display:"flex", alignItems:"center", gap:12 }}>
      <LogoSeal size="sm" />
      <div>
        <div style={{ fontFamily:"'Playfair Display',serif", fontWeight:800, fontSize:15, lineHeight:1.2 }}>Lácteos de Oriente</div>
        <div style={{ fontSize:10, color:"rgba(255,255,255,0.45)", letterSpacing:"0.08em" }}>LO FRESCO MEJOR</div>
      </div>
    </div>
  );
}

const NAV = [
  { path:"/dashboard",    label:"Dashboard",    icon:LayoutDashboard },
  { path:"/analisis",     label:"Análisis",     icon:Activity },
  { path:"/inventario",   label:"Inventario",   icon:Package },
  { path:"/trazabilidad", label:"Trazabilidad", icon:GitBranch },
  { path:"/alertas",      label:"Alertas",      icon:Bell },
  { path:"/configuracion",label:"Configuración",icon:Settings },
];

export function Sidebar({ usuario }) {
  const navigate = useNavigate();
  const location = useLocation();
  return (
    <aside style={{ width:228, background:"rgba(10,22,40,0.97)", borderRight:"1px solid rgba(255,255,255,0.09)", display:"flex", flexDirection:"column", height:"100vh", flexShrink:0, position:"sticky", top:0 }}>
      <div style={{ padding:"18px 16px", borderBottom:"1px solid rgba(255,255,255,0.08)" }}><LogoBanner /></div>
      <nav style={{ flex:1, padding:10, display:"flex", flexDirection:"column", gap:3, overflowY:"auto" }}>
        {NAV.map(({ path, label, icon:Icon }) => (
          <button key={path} onClick={() => navigate(path)} className={`nav-item ${location.pathname===path?"active":""}`}>
            <Icon size={16} /><span>{label}</span>
          </button>
        ))}
      </nav>
      <button onClick={() => navigate("/perfil")} style={{ display:"flex", alignItems:"center", gap:10, padding:"14px 16px", borderTop:"1px solid rgba(255,255,255,0.08)", background:"none", border:"none", cursor:"pointer", transition:"background 0.2s", width:"100%", textAlign:"left" }}
        onMouseEnter={e=>e.currentTarget.style.background="rgba(255,255,255,0.04)"}
        onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
        <div style={{ width:34, height:34, borderRadius:"50%", flexShrink:0, background:"linear-gradient(135deg,#2456a4,#163059)", border:"1.5px solid rgba(255,255,255,0.35)", display:"flex", alignItems:"center", justifyContent:"center", fontSize:12, fontWeight:800, color:"#fff" }}>{usuario?.initials||"CM"}</div>
        <div>
          <div style={{ fontSize:13, fontWeight:600, color:"#fff" }}>{usuario?.nombre||"Carlos Méndez"}</div>
          <div style={{ fontSize:11, color:"rgba(255,255,255,0.40)" }}>{usuario?.rol||"Operador"}</div>
        </div>
      </button>
    </aside>
  );
}

export function TopBar({ sensorOk=true, numAlertas=2 }) {
  const navigate = useNavigate();
  const [menu, setMenu] = useState(false);
  return (
    <header style={{ display:"flex", alignItems:"center", justifyContent:"flex-end", gap:20, padding:"13px 28px", background:"rgba(10,22,40,0.85)", backdropFilter:"blur(14px)", borderBottom:"1px solid rgba(255,255,255,0.08)", position:"sticky", top:0, zIndex:50 }}>
      <div style={{ display:"flex", alignItems:"center", gap:8, fontSize:12, fontWeight:600, color:sensorOk?"#6a9fd8":"#e74c3c" }}>
        <span style={{ width:8, height:8, borderRadius:"50%", display:"inline-block", background:sensorOk?"#6a9fd8":"#e74c3c", boxShadow:sensorOk?"0 0 6px #6a9fd8":"none" }} />
        {sensorOk?"Sensor conectado":"Sensor desconectado"}
      </div>
      <button onClick={()=>navigate("/alertas")} style={{ background:"none", border:"none", cursor:"pointer", position:"relative", color:"rgba(255,255,255,0.55)" }}>
        <Bell size={19}/>
        {numAlertas>0&&<span style={{ position:"absolute", top:-6, right:-6, background:"#e74c3c", borderRadius:"50%", width:16, height:16, fontSize:10, fontWeight:700, color:"#fff", display:"flex", alignItems:"center", justifyContent:"center" }}>{numAlertas}</span>}
      </button>
      <div style={{ position:"relative" }}>
        <button onClick={()=>setMenu(!menu)} style={{ width:32, height:32, borderRadius:"50%", background:"linear-gradient(135deg,#2456a4,#163059)", border:"1.5px solid rgba(255,255,255,0.35)", cursor:"pointer", fontWeight:800, fontSize:12, color:"#fff", display:"flex", alignItems:"center", justifyContent:"center" }}>CM</button>
        {menu&&(
          <div className="navy-card" style={{ position:"absolute", right:0, top:40, borderRadius:12, padding:8, minWidth:178, zIndex:100, boxShadow:"0 20px 60px rgba(0,0,0,0.6)" }}>
            <div style={{ padding:"8px 12px", borderBottom:"1px solid rgba(255,255,255,0.08)", marginBottom:4 }}>
              <div style={{ fontSize:13, fontWeight:600 }}>Carlos Méndez</div>
              <div style={{ fontSize:11, color:"#6a9fd8" }}>Operador</div>
            </div>
            {[{label:"Ver Perfil",icon:User,go:"/perfil"},{label:"Configuración",icon:Settings,go:"/configuracion"}].map(({label,icon:Icon,go})=>(
              <button key={label} onClick={()=>{navigate(go);setMenu(false);}} style={{ display:"flex", alignItems:"center", gap:10, width:"100%", padding:"10px 12px", borderRadius:8, fontSize:13, color:"rgba(255,255,255,0.75)", background:"none", border:"none", cursor:"pointer", fontFamily:"Inter,sans-serif", textAlign:"left" }}
                onMouseEnter={e=>e.currentTarget.style.background="rgba(255,255,255,0.07)"}
                onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
                <Icon size={14}/>{label}
              </button>
            ))}
            <div style={{ borderTop:"1px solid rgba(255,255,255,0.08)", marginTop:4, paddingTop:4 }}>
              <button onClick={()=>navigate("/")} style={{ display:"flex", alignItems:"center", gap:10, width:"100%", padding:"10px 12px", borderRadius:8, fontSize:13, color:"#e74c3c", background:"none", border:"none", cursor:"pointer", fontFamily:"Inter,sans-serif", textAlign:"left" }}
                onMouseEnter={e=>e.currentTarget.style.background="rgba(231,76,60,0.08)"}
                onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
                <LogOut size={14}/>Cerrar Sesión
              </button>
            </div>
          </div>
        )}
      </div>
    </header>
  );
}
